insert into public.lessons (category, level, title, body, sort_order) values ('how_to_sell', 'beginner', 'The Best Flow: Pitch → Demo → Follow-up → Close', E'1. Pitch: send the copy-paste pitch to 10 warm contacts a day.\n2. Demo: share the product video or brochure only to people who reply.\n3. Follow-up: message again after 24 hours, then after 3 days.\n4. Close: send your partner link and help them complete payment.', 1);
insert into public.lessons (category, level, title, body, sort_order) values ('how_to_sell', 'beginner', 'Where to find your first 5 customers', 'Start with people who already trust you: family groups, society/parent groups, college friends, office colleagues. Post once in a group, then follow up 1-on-1 — personal messages convert 5× better than group posts.', 2);
insert into public.lessons (category, level, title, body, sort_order) values ('branding', 'intermediate', 'Personal branding on WhatsApp Status', 'Post one useful tip a day (study hack, tax deadline, parenting tip) and one product post every 3 days. Share real results and screenshots of happy customers (with permission). Consistency builds trust.', 3);
insert into public.lessons (category, level, title, body, sort_order) values ('branding', 'intermediate', 'Instagram basics for partners', 'Use a clear profile photo and bio: “Education partner | Helping parents & students grow”. Post Reels of product unboxing or course highlights. Put your partner link in bio.', 4);
insert into public.lessons (category, level, title, body, sort_order) values ('about', 'beginner', 'How your commission works', 'Every product shows its exact commission %. When a buyer pays through your link, commission is credited to your wallet automatically. If an order is cancelled or refunded, that commission is reversed. You earn only from sales — never from recruiting people.', 5);
